#include <SymbolicRegression.hpp>
#include <ScalarExpressionCheckpoint.hpp>
#include <DiscreteRunCheckpoint.hpp>
#include <fstream>
int main(int argc,char** argv){if(argc!=2)return 2;CheckpointWriter writer;for(unsigned workers:{1U,2U,4U}){auto problem=RegressionProblem::create({{{0},.1},{{1},1.4},{{2},2.7}});SymbolicRegressionConfig config;config.population=8;config.maxGenerationAttempts=8;config.maxEvaluations=72;config.maxTrainingLossAttempts=72;RandomContext random(42,{workers});auto result=symbolicRegression(problem,config,random);if(!result.best)return 3;writer.text(result.best->text());writer.real(result.best->fitness());writer.text(RunCheckpointAccess::random(random).engine);writeTrainingWork(writer,result.trainingWork);writeVariationStatistics(writer,result.variation);auto p=DiscreteRegressionProblem::create(1,{{{0},1},{{1},2},{{1},3}});DiscreteSearchConfig c;c.population=8;c.elites=1;c.maxGenerations=8;c.maxLossAttempts=72;RandomContext rng(42,{workers});DiscreteEvolutionRun run(p,c,rng);while(!run.stoppingReason())run.step();writer.text(run.checkpoint().payload);}std::ofstream file(argv[1],std::ios::binary);file<<writer.data();return !file;}

