#include <ScalarMathematicsRun.hpp>
#include <IntegerRecurrence.hpp>
#include <SymbolicAlgebra.hpp>
#include <ExpressionParsing.hpp>
#include <DiscreteExpressionParsing.hpp>
#include <iostream>
int other();
int main(){
    IntegerRecurrence f(0,{0,1},parseDiscreteExpression("x1+x2",3));
    if(f.evaluate(10).value->integer()!=55 || other()!=3)return 1;
    auto p=SymbolicExpression::fromExpression(parseExpression("(x0+2)*(x0-2)",1)).expandPolynomial();
    if(p.status!=SymbolicStatus::Success)return 2;
    auto L=PhysicalDimension::base(SIBaseDimension::Length),T=PhysicalDimension::base(SIBaseDimension::Time);
    if(DimensionalExpression(parseExpression("x0/x1",2),{L,T}).dimension()!=L/T)return 3;
    std::cout<<"Installed advanced headers linked across two translation units\n";
}

