#include <DimensionalRegression.hpp>
#include <ExpressionParsing.hpp>
#include <iostream>
int main(){
    std::vector<PhysicalDimension> supplied{PhysicalDimension::base(SIBaseDimension::Length)};
    auto* retained=supplied.data();
    DimensionalConstantSelection selection(std::move(supplied));
    *retained=PhysicalDimension{};
    if(selection.parameters(parseExpression("2*pow(x0,2)",1)).size()!=1){
        std::cerr<<"Moved caller storage must not alias the dimensional fitting policy\n";
        return 1;
    }
    std::cout<<"Detached dimensional policy ownership verified\n";
}
